validator:
function validate(input) {
  const [{ Orders = [] }] = input;
  const ids = new Set();
  for (const [id, items, occurrences] of Orders) {
    if (id === null || items === null || occurrences === null) return 'Orders cannot contain null values.';
    if (ids.has(id)) return `order_id ${id} appears twice.`;
    if (items < 1) return 'item_count must be at least 1.';
    if (occurrences < 1) return 'order_occurrences must be at least 1.';
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const count = size === 'small' ? Math.floor(rand() * 7) : 1500 + Math.floor(rand() * 500);
  const maxItems = size === 'small' ? 5 : 20, maxOccurrences = size === 'small' ? 12 : 10;
  const Orders = [];
  let id = 1 + Math.floor(rand() * 20);
  for (let i = 0; i < count; i++) {
    Orders.push([id, 1 + Math.floor(rand() * maxItems), 1 + Math.floor(rand() * maxOccurrences)]);
    id += 1 + Math.floor(rand() * 3);
  }
  return [{ Orders }];
}
